//! Wayland protocols without a Smithay frontend: the KDE application menu address protocol
//! (generated by `wayland-protocols-plasma`) and the GTK shell extension (generated here from
//! `protocols/gtk-shell.xml`), both used to learn where a client exports its menus.

use std::sync::Mutex;
use std::time::Duration;

use cupertino_wm::WindowId;
use smithay::reexports::calloop::timer::{TimeoutAction, Timer};
use smithay::reexports::calloop::RegistrationToken;
use smithay::reexports::wayland_server::backend::ObjectId;
use smithay::reexports::wayland_server::protocol::wl_surface::WlSurface;
use smithay::reexports::wayland_server::{
    Client, DataInit, Dispatch, DisplayHandle, GlobalDispatch, New, Resource,
};
use wayland_protocols_plasma::appmenu::server::org_kde_kwin_appmenu::{self, OrgKdeKwinAppmenu};
use wayland_protocols_plasma::appmenu::server::org_kde_kwin_appmenu_manager::{
    self, OrgKdeKwinAppmenuManager,
};

use crate::menu_bar::{
    is_unique_bus_name, retryable, Announced, GtkMenuProps, MenuAddress, MenuKind, Refused,
};
use crate::owner_check::{OwnerCheck, OwnerKey, OwnerRefusal};
use crate::state::Cupertino;

// The scanner macros read the XML without telling rustc; including it puts it in the dep-info that caches such as
// sccache key on, so an edited protocol regenerates the bindings.
const _: &[u8] = include_bytes!("../protocols/gtk-shell.xml");

pub mod gtk_shell {
    #![allow(
        dead_code,
        non_camel_case_types,
        unused_unsafe,
        unused_variables,
        non_upper_case_globals,
        non_snake_case,
        unused_imports,
        missing_docs,
        clippy::all
    )]
    use wayland_server;
    use wayland_server::protocol::*;

    pub mod __interfaces {
        use wayland_server::protocol::__interfaces::*;
        wayland_scanner::generate_interfaces!("protocols/gtk-shell.xml");
    }
    use self::__interfaces::*;

    wayland_scanner::generate_server_code!("protocols/gtk-shell.xml");
}

use gtk_shell::gtk_shell1::{self, GtkShell1};
use gtk_shell::gtk_surface1::{self, GtkSurface1};

/// Per-object data: the surface an address belongs to.
pub struct SurfaceData {
    pub surface: WlSurface,
    pub gtk: Mutex<GtkMenuProps>,
}

/// Registers the globals.
pub struct MenuProtocols {
    _appmenu: smithay::reexports::wayland_server::backend::GlobalId,
    _gtk: smithay::reexports::wayland_server::backend::GlobalId,
    /// Bound `gtk_shell1` objects.
    gtk_shells: Vec<GtkShell1>,
    /// The `gtk_shell1` capabilities last sent.
    gtk_capabilities: u32,
}

impl MenuProtocols {
    pub fn new(dh: &DisplayHandle) -> Self {
        Self {
            _appmenu: dh.create_global::<Cupertino, OrgKdeKwinAppmenuManager, ()>(2, ()),
            _gtk: dh.create_global::<Cupertino, GtkShell1, ()>(7, ()),
            gtk_shells: Vec::new(),
            gtk_capabilities: 0,
        }
    }
}

impl GlobalDispatch<OrgKdeKwinAppmenuManager, ()> for Cupertino {
    fn bind(
        _: &mut Self,
        _: &DisplayHandle,
        _: &Client,
        resource: New<OrgKdeKwinAppmenuManager>,
        _: &(),
        init: &mut DataInit<'_, Self>,
    ) {
        init.init(resource, ());
    }
}

impl Dispatch<OrgKdeKwinAppmenuManager, ()> for Cupertino {
    fn request(
        _: &mut Self,
        _: &Client,
        _: &OrgKdeKwinAppmenuManager,
        request: org_kde_kwin_appmenu_manager::Request,
        _: &(),
        _: &DisplayHandle,
        init: &mut DataInit<'_, Self>,
    ) {
        if let org_kde_kwin_appmenu_manager::Request::Create { id, surface } = request {
            init.init(
                id,
                SurfaceData {
                    surface,
                    gtk: Mutex::new(GtkMenuProps::default()),
                },
            );
        }
    }
}

impl Dispatch<OrgKdeKwinAppmenu, SurfaceData> for Cupertino {
    fn request(
        state: &mut Self,
        _: &Client,
        _: &OrgKdeKwinAppmenu,
        request: org_kde_kwin_appmenu::Request,
        data: &SurfaceData,
        _: &DisplayHandle,
        _: &mut DataInit<'_, Self>,
    ) {
        match request {
            org_kde_kwin_appmenu::Request::SetAddress {
                service_name,
                object_path,
            } => {
                state.announce_menu_address(
                    &data.surface,
                    MenuAddress::DbusMenu {
                        service: service_name,
                        path: object_path,
                    },
                );
            }
            org_kde_kwin_appmenu::Request::Release => {
                state.withdraw_menu_address(&data.surface, MenuKind::DbusMenu)
            }
            _ => {}
        }
    }
}

impl GlobalDispatch<GtkShell1, ()> for Cupertino {
    fn bind(
        state: &mut Self,
        _: &DisplayHandle,
        _: &Client,
        resource: New<GtkShell1>,
        _: &(),
        init: &mut DataInit<'_, Self>,
    ) {
        let shell = init.init(resource, ());
        let protocols = &mut state.menu_protocols;
        if protocols.gtk_capabilities != 0 {
            shell.capabilities(protocols.gtk_capabilities);
        }
        protocols.gtk_shells.retain(Resource::is_alive);
        protocols.gtk_shells.push(shell);
    }
}

impl Dispatch<GtkShell1, ()> for Cupertino {
    fn request(
        _: &mut Self,
        _: &Client,
        _: &GtkShell1,
        request: gtk_shell1::Request,
        _: &(),
        _: &DisplayHandle,
        init: &mut DataInit<'_, Self>,
    ) {
        if let gtk_shell1::Request::GetGtkSurface {
            gtk_surface,
            surface,
        } = request
        {
            init.init(
                gtk_surface,
                SurfaceData {
                    surface,
                    gtk: Mutex::new(GtkMenuProps::default()),
                },
            );
        }
    }
}

impl Dispatch<GtkSurface1, SurfaceData> for Cupertino {
    fn request(
        state: &mut Self,
        _: &Client,
        _: &GtkSurface1,
        request: gtk_surface1::Request,
        data: &SurfaceData,
        _: &DisplayHandle,
        _: &mut DataInit<'_, Self>,
    ) {
        match request {
            gtk_surface1::Request::SetDbusProperties {
                application_id,
                app_menu_path,
                menubar_path,
                window_object_path,
                application_object_path,
                unique_bus_name,
            } => {
                let props = GtkMenuProps {
                    bus_name: unique_bus_name.unwrap_or_default(),
                    application_id,
                    application_object_path,
                    window_object_path,
                    menubar_object_path: menubar_path,
                    app_menu_object_path: app_menu_path,
                };
                *data.gtk.lock().expect("gtk props") = props.clone();
                if props.has_menus() && !props.bus_name.is_empty() {
                    state.announce_menu_address(&data.surface, MenuAddress::Gtk(props));
                } else {
                    state.withdraw_menu_address(&data.surface, MenuKind::Gtk);
                }
            }
            gtk_surface1::Request::Present { .. } => state.gtk_focus_request(&data.surface, None),
            gtk_surface1::Request::RequestFocus { startup_id } => {
                state.gtk_focus_request(&data.surface, startup_id.as_deref())
            }
            gtk_surface1::Request::Release => {
                state.withdraw_menu_address(&data.surface, MenuKind::Gtk)
            }
            _ => {}
        }
    }
}

impl Cupertino {
    /// Tell GTK clients whether a menu bar shows their menus: `global_menu_bar` only while the menu bar process has a
    /// bar, so a GTK window hides its own menu bar only when ours takes its place. Call after a bar comes or goes.
    pub fn refresh_gtk_capabilities(&mut self) {
        let capabilities = if self.menu_bars.is_empty() {
            0
        } else {
            gtk_shell1::Capability::GlobalMenuBar as u32
        };
        let protocols = &mut self.menu_protocols;
        if capabilities == protocols.gtk_capabilities {
            return;
        }
        protocols.gtk_capabilities = capabilities;
        protocols.gtk_shells.retain(Resource::is_alive);
        for shell in &protocols.gtk_shells {
            shell.capabilities(capabilities);
        }
    }

    /// A client announced where `surface` exports its menus. The surface has no menus of the address's kind until the
    /// owner of the bus name is checked to be the client or its sandbox instance (`crate::owner_check`); an address of
    /// the other kind stays meanwhile.
    /// An address with a malformed or overlong name or path gives no menus.
    pub fn announce_menu_address(&mut self, surface: &WlSurface, address: MenuAddress) {
        let kind = address.kind();
        if !address.within_limits() {
            if self.menu_bars.over_limits(surface.id()) {
                tracing::warn!(
                    ?kind,
                    "a window announced its menus with a malformed or overlong bus name, object path or application \
                     id: the menu bar is not told of it, and later such announcements of this surface are not logged"
                );
            }
            self.withdraw_menu_address(surface, kind);
            return;
        }
        self.set_menu_address(surface, kind, None);
        if surface.client().is_none() {
            return;
        }
        if let Some(replaced) = self.menu_bars.announce(surface, address) {
            self.drop_menu_retry(replaced.timer);
        }
        self.check_menu_owner(&surface.id(), kind);
    }

    /// Check the owner of the bus name of the address of kind `kind` `surface` announced.
    fn check_menu_owner(&mut self, surface: &ObjectId, kind: MenuKind) {
        let Some(announced) = self.menu_bars.announced(surface, kind) else {
            return;
        };
        let Some(client) = announced.surface.client() else {
            return;
        };
        let name = announced.address.bus_name().to_owned();
        self.check_owner(OwnerCheck {
            key: OwnerKey::MenuAddress(surface.clone(), kind),
            name,
            client,
        });
    }

    /// The client withdrew the menu export of kind `kind` of `surface`.
    pub fn withdraw_menu_address(&mut self, surface: &WlSurface, kind: MenuKind) {
        self.cancel_menu_check(surface, kind);
        self.set_menu_address(surface, kind, None);
    }

    /// `surface` is gone: the checks of its announcements are cancelled.
    pub fn menu_surface_destroyed(&mut self, surface: &WlSurface) {
        self.menu_bars.forget_over_limits(&surface.id());
        self.cancel_menu_check(surface, MenuKind::Gtk);
        self.cancel_menu_check(surface, MenuKind::DbusMenu);
    }

    /// `window` became the key window: each announcement of its surfaces whose owner checks ran out of retries is
    /// checked once more, with its retries counted afresh.
    pub fn recheck_menu_owners(&mut self, window: WindowId) {
        let Some(root) = self.entry(window).map(|e| e.surface().clone()) else {
            return;
        };
        let announced: Vec<_> = self
            .menu_bars
            .announced_surfaces()
            .filter(|(surface, _)| {
                self.root_window_surface(surface)
                    .as_ref()
                    .unwrap_or(surface)
                    == &root
            })
            .map(|(surface, kind)| (surface.id(), kind))
            .collect();
        for (surface, kind) in announced {
            let recheck = self
                .menu_bars
                .announced_mut(&surface, kind)
                .is_some_and(|a| a.retry.recheck());
            if recheck {
                self.check_menu_owner(&surface, kind);
            }
        }
    }

    fn cancel_menu_check(&mut self, surface: &WlSurface, kind: MenuKind) {
        if let Some(announced) = self.menu_bars.take_announced(&surface.id(), kind) {
            self.drop_menu_retry(announced.timer);
        }
        self.cancel_owner_check(&OwnerKey::MenuAddress(surface.id(), kind));
    }

    fn drop_menu_retry(&mut self, timer: Option<RegistrationToken>) {
        if let Some(token) = timer {
            self.loop_handle.remove(token);
        }
    }

    /// Retry the owner check of announcement `announcement` of kind `kind` of `surface` after `after`.
    fn arm_menu_retry(
        &mut self,
        surface: ObjectId,
        kind: MenuKind,
        announcement: u64,
        after: Duration,
    ) {
        let timer_surface = surface.clone();
        let armed =
            self.loop_handle
                .insert_source(Timer::from_duration(after), move |_, _, state| {
                    state.menu_retry_due(&timer_surface, kind, announcement);
                    TimeoutAction::Drop
                });
        match armed {
            Ok(token) => match self.menu_bars.announced_mut(&surface, kind) {
                Some(announced) => announced.timer = Some(token),
                None => self.loop_handle.remove(token),
            },
            Err(e) => {
                tracing::warn!(error = %e, "cannot time a retry of a menu owner check: it waits for the window to be key");
                if let Some(announced) = self.menu_bars.announced_mut(&surface, kind) {
                    announced.retry.untimed();
                }
            }
        }
    }

    /// The retry of announcement `announcement` of kind `kind` of `surface` is due: its check is sent again unless a
    /// newer announcement replaced it, it was withdrawn, or the surface is gone.
    fn menu_retry_due(&mut self, surface: &ObjectId, kind: MenuKind, announcement: u64) {
        let Some(announced) = self.menu_bars.announced_mut(surface, kind) else {
            return;
        };
        announced.timer = None;
        if announced.surface.is_alive() && announced.retry.due(announcement) {
            self.check_menu_owner(surface, kind);
        }
    }

    /// The check of the latest announcement of kind `kind` of `surface` returned: on a match the address is read from
    /// the owner's unique name; a refusal that may pass is retried, up to [`crate::menu_bar::OWNER_RETRY_DELAYS`], and
    /// then checked again when the window becomes the key window; else the surface has no menus of that kind.
    pub(crate) fn menu_owner_checked(
        &mut self,
        surface: ObjectId,
        kind: MenuKind,
        verdict: Result<String, OwnerRefusal>,
    ) {
        let Some(announced) = self.menu_bars.announced_mut(&surface, kind) else {
            return;
        };
        if let (true, Err(refusal)) = (announced.surface.is_alive(), &verdict) {
            let announcement = announced.retry.announcement();
            match announced.retry.refused(retryable(refusal)) {
                // a refusal comes only for a check that went out, and a check goes out with its timer gone
                Refused::Final => debug_assert!(announced.timer.is_none()),
                Refused::RetryAfter(after) => {
                    self.arm_menu_retry(surface, kind, announcement, after);
                    return;
                }
                Refused::RanOut { warn } => {
                    if warn {
                        tracing::warn!(
                            name = ?announced.address.bus_name(),
                            ?refusal,
                            "the owner of the bus name a window announced for its menus could not be checked, \
                             retries included: it is checked again when the window becomes the key window"
                        );
                    }
                    return;
                }
            }
        }
        let Some(Announced {
            surface, address, ..
        }) = self.menu_bars.take_announced(&surface, kind)
        else {
            return;
        };
        if !surface.is_alive() {
            return;
        }
        match verdict {
            Ok(owner) if is_unique_bus_name(&owner) => {
                self.set_menu_address(&surface, kind, Some(address.with_bus_name(owner)))
            }
            Ok(owner) => tracing::warn!(
                ?owner,
                "the owner of the bus name a window announced for its menus is not a unique bus name: the menu bar is \
                 not told of it"
            ),
            Err(refusal) => tracing::warn!(
                name = ?address.bus_name(),
                ?refusal,
                "the bus name a window announced for its menus is not its own: the menu bar is not told of it"
            ),
        }
    }

    /// Set (or withdraw) the menu address of kind `kind` of `surface`; only a checked address is set.
    pub fn set_menu_address(
        &mut self,
        surface: &WlSurface,
        kind: MenuKind,
        address: Option<MenuAddress>,
    ) {
        let root = self
            .root_window_surface(surface)
            .unwrap_or_else(|| surface.clone());
        match self.entry_for_surface(&root).map(|e| e.id.0) {
            Some(key) => self.menu_bars.set_address(key, kind, address),
            None => self.menu_bars.set_pending(surface, kind, address),
        }
        self.refresh_menu_bars();
    }

    /// Apply menu addresses announced before the window mapped.
    pub fn apply_pending_menu_addresses(&mut self, window: u64, root: &WlSurface) {
        for address in self.menu_bars.take_pending(root) {
            self.menu_bars
                .set_address(window, address.kind(), Some(address));
        }
    }
}
